//! 📏️ Borrowed GLTF domains admit bounded logical encoding before any owned lowering.
use super::*;
use semio_framework_os_kernel::sqlite_snapshot::artifact::NativeEncodingBound;
type Bound<'a,'p>=NativeEncodingBound<'a,'p>;
fn text(bound:&mut Bound<'_,'_>,value:&str)->Result<(), ValueError>{bound.repeated(value.len(),6)}
fn optional_text(bound:&mut Bound<'_,'_>,value:&Option<String>)->Result<(), ValueError>{if let Some(value)=value{text(bound,value)?;}Ok(())}
fn json(bound:&mut Bound<'_,'_>,value:&Option<GltfJson>)->Result<(), ValueError>{let Some(value)=value else{return Ok(())};let mut pending=bound.allocate_frontier(1)?;bound.push_frontier(&mut pending,value)?;while let Some(value)=pending.pop(){bound.add(128)?;match value{GltfJson::Null|GltfJson::Bool(_)=>{},GltfJson::Number(_)=>bound.add(1100)?,GltfJson::String(value)=>text(bound,value)?,GltfJson::Array(values)=>{bound.repeated(values.len(),128)?;for child in values{bound.push_frontier(&mut pending,child)?;}},GltfJson::Object(values)=>{bound.repeated(values.len(),128)?;for(name,value)in values{text(bound,name)?;pending.push(value);}}}}Ok(())}
fn extras(bound:&mut Bound<'_,'_>,extensions:&Option<GltfJson>,extra:&Option<GltfJson>)->Result<(), ValueError>{json(bound,extensions)?;json(bound,extra)}
fn texture(bound:&mut Bound<'_,'_>,value:&Option<GltfTextureInfo>)->Result<(), ValueError>{if let Some(value)=value{bound.add(512)?;extras(bound,&value.extensions,&value.extras)?;}Ok(())}
pub(super) fn native_footprint(snapshot:&GltfSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(), ValueError>{
 let mut bound=NativeEncodingBound::new(control)?;bound.add(2048)?;text(&mut bound,&snapshot.schema)?;let document=&snapshot.document;
 text(&mut bound,&document.asset.version)?;optional_text(&mut bound,&document.asset.generator)?;optional_text(&mut bound,&document.asset.copyright)?;optional_text(&mut bound,&document.asset.min_version)?;extras(&mut bound,&document.asset.extensions,&document.asset.extras)?;
 for value in &document.scenes{bound.add(512)?;bound.repeated(value.nodes.len(),32)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.nodes{bound.add(1536)?;bound.repeated(value.children.len(),32)?;if value.matrix.is_some(){bound.repeated(16,1100)?;}if value.translation.is_some(){bound.repeated(3,1100)?;}if value.rotation.is_some(){bound.repeated(4,1100)?;}if value.scale.is_some(){bound.repeated(3,1100)?;}bound.repeated(value.weights.len(),1100)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.meshes{bound.add(512)?;bound.repeated(value.weights.len(),1100)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;for primitive in &value.primitives{bound.add(1024)?;for(name,_)in &primitive.attributes{bound.add(128)?;text(&mut bound,name)?;}for target in &primitive.targets{bound.add(128)?;for(name,_)in &target.0{bound.add(128)?;text(&mut bound,name)?;}}extras(&mut bound,&primitive.extensions,&primitive.extras)?;}}
 for value in &document.buffers{bound.add(512)?;optional_text(&mut bound,&value.uri)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.buffer_views{bound.add(1024)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.accessors{bound.add(1024)?;optional_text(&mut bound,&value.name)?;if let Some(values)=&value.max{bound.repeated(values.len(),1100)?;}if let Some(values)=&value.min{bound.repeated(values.len(),1100)?;}if value.sparse.is_some(){bound.add(1024)?;}extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.materials{bound.add(2048)?;bound.repeated(4,1100)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;texture(&mut bound,&value.emissive_texture)?;if let Some(value)=&value.pbr_metallic_roughness{bound.add(1024)?;bound.repeated(6,1100)?;texture(&mut bound,&value.base_color_texture)?;texture(&mut bound,&value.metallic_roughness_texture)?;extras(&mut bound,&value.extensions,&value.extras)?;}if let Some(value)=&value.normal_texture{bound.add(1024)?;bound.add(1100)?;extras(&mut bound,&value.extensions,&value.extras)?;}if let Some(value)=&value.occlusion_texture{bound.add(1024)?;bound.add(1100)?;extras(&mut bound,&value.extensions,&value.extras)?;}}
 for value in &document.textures{bound.add(1024)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.images{bound.add(1024)?;optional_text(&mut bound,&value.name)?;optional_text(&mut bound,&value.uri)?;optional_text(&mut bound,&value.mime_type)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.samplers{bound.add(1024)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.skins{bound.add(1024)?;bound.repeated(value.joints.len(),32)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;}
 for value in &document.animations{bound.add(512)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;for value in &value.samplers{bound.add(1024)?;extras(&mut bound,&value.extensions,&value.extras)?;}for value in &value.channels{bound.add(1024)?;extras(&mut bound,&value.extensions,&value.extras)?;bound.add(512)?;extras(&mut bound,&value.target.extensions,&value.target.extras)?;}}
 for value in &document.cameras{bound.add(1024)?;optional_text(&mut bound,&value.name)?;extras(&mut bound,&value.extensions,&value.extras)?;bound.repeated(4,1100)?;match &value.projection{GltfCameraProjection::Perspective(value)=>extras(&mut bound,&value.extensions,&value.extras)?,GltfCameraProjection::Orthographic(value)=>extras(&mut bound,&value.extensions,&value.extras)?,}}
 for value in &document.extensions_used{bound.add(64)?;text(&mut bound,value)?;}for value in &document.extensions_required{bound.add(64)?;text(&mut bound,value)?;}extras(&mut bound,&document.extensions,&document.extras)?;
 for buffer in &snapshot.buffers{bound.add(64)?;bound.repeated(buffer.len(),8)?;}bound.finish()
}
